import AppKit
import Combine

/// Opt-in, memory-only text history. Never reads the pasteboard while disabled.
final class ClipboardController: ObservableObject {
    static let limit = 20
    /// Entries above this are skipped to bound memory.
    static let maxLength = 100_000
    /// Pasteboard types that mark content as secret, transient or machine-generated (nspasteboard.org + common managers).
    static let skippedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword", "de.petermaurer.TransientPasteboardType", "com.typeit4me.clipping",
        "Pasteboard generator type",
    ]

    @Published private(set) var entries: [String] = []

    private let preferences: Preferences
    private let pasteboard: NSPasteboard
    private var timer: Timer?
    private var lastCount = 0
    private var ownCount = -1
    private var cancellable: AnyCancellable?

    init(preferences: Preferences, pasteboard: NSPasteboard = .general) {
        self.preferences = preferences
        self.pasteboard = pasteboard
        cancellable = preferences.$clipboardEnabled.removeDuplicates().sink { [weak self] in self?.apply(enabled: $0) }
    }

    func shutdown() {
        cancellable = nil
        timer?.invalidate(); timer = nil
    }

    private func apply(enabled: Bool) {
        timer?.invalidate(); timer = nil
        guard enabled else { entries = []; return }
        // Baseline only: whatever is on the pasteboard now predates opt-in and is not read.
        lastCount = pasteboard.changeCount
        let t = Timer(timeInterval: 1, repeats: true) { [weak self] _ in self?.poll() }
        t.tolerance = 0.2
        RunLoop.main.add(t, forMode: .common)
        timer = t
    }

    private func poll() {
        guard preferences.clipboardEnabled else { return }
        let count = pasteboard.changeCount
        guard count != lastCount else { return }
        lastCount = count
        if count == ownCount { return }
        let types = (pasteboard.types ?? []).map(\.rawValue)
        guard Self.shouldCapture(types: types), let text = pasteboard.string(forType: .string) else { return }
        entries = Self.inserting(text, into: entries)
    }

    /// Click-to-copy: writes without reordering or recapturing.
    func copy(_ text: String) {
        pasteboard.clearContents()
        pasteboard.setString(text, forType: .string)
        ownCount = pasteboard.changeCount
    }

    func clear() { entries = [] }

    // MARK: pure policy

    static func shouldCapture(types: [String]) -> Bool {
        types.contains(NSPasteboard.PasteboardType.string.rawValue) && skippedTypes.isDisjoint(with: types)
    }

    /// Newest first, distinct, capped; blank or oversize text is ignored.
    static func inserting(_ text: String, into list: [String]) -> [String] {
        guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty, text.count <= maxLength else { return list }
        return Array(([text] + list.filter { $0 != text }).prefix(limit))
    }

    static func selftest() throws {
        func check(_ ok: Bool, _ msg: String) throws {
            if !ok { throw NSError(domain: "ClipboardSelfTest", code: 1, userInfo: [NSLocalizedDescriptionKey: msg]) }
        }
        let s = NSPasteboard.PasteboardType.string.rawValue
        try check(shouldCapture(types: [s]), "plain text captured")
        try check(!shouldCapture(types: [s, "org.nspasteboard.ConcealedType"]), "concealed skipped")
        try check(!shouldCapture(types: [s, "org.nspasteboard.TransientType"]), "transient skipped")
        try check(!shouldCapture(types: [s, "org.nspasteboard.AutoGeneratedType"]), "autogenerated skipped")
        try check(!shouldCapture(types: ["public.png"]), "non-text skipped")
        var list: [String] = []
        for i in 0..<25 { list = inserting("t\(i)", into: list) }
        try check(list.count == 20 && list.first == "t24" && list.last == "t5", "cap 20 newest first")
        list = inserting("t10", into: list)
        try check(list.count == 20 && list.first == "t10" && list.filter { $0 == "t10" }.count == 1, "distinct moves to front")
        try check(inserting("  \n", into: list) == list, "blank ignored")
    }
}
